import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createClient } from "@supabase/supabase-js";
import { createChannelName, REMOTE_EVENT } from "./eventProtocol";

let cachedClient = null;

const getSupabaseClient = () => {
  if (typeof window === "undefined") return null;
  if (cachedClient) return cachedClient;

  const url = process.env.GATSBY_SUPABASE_URL;
  const anonKey = process.env.GATSBY_SUPABASE_ANON_KEY;

  if (!url || !anonKey) {
    return null;
  }

  cachedClient = createClient(url, anonKey, {
    auth: { persistSession: false },
    realtime: { params: { eventsPerSecond: 60 } },
  });

  return cachedClient;
};

export const useRemoteSession = ({ sid, enabled = true, onEvent, onStatus }) => {
  const [status, setStatus] = useState("idle");
  const [error, setError] = useState("");
  const channelRef = useRef(null);
  const onEventRef = useRef(onEvent);
  const onStatusRef = useRef(onStatus);

  onEventRef.current = onEvent;
  onStatusRef.current = onStatus;

  const client = useMemo(() => getSupabaseClient(), []);
  const hasConfig = Boolean(process.env.GATSBY_SUPABASE_URL && process.env.GATSBY_SUPABASE_ANON_KEY);

  useEffect(() => {
    if (!enabled || !sid) return undefined;

    if (!client) {
      setStatus("error");
      setError("Supabase is not configured. Set GATSBY_SUPABASE_URL and GATSBY_SUPABASE_ANON_KEY.");
      return undefined;
    }

    const channel = client.channel(createChannelName(sid), {
      config: { broadcast: { self: true } },
    });
    channelRef.current = channel;

    channel
      .on("broadcast", { event: REMOTE_EVENT }, event => {
        onEventRef.current?.(event.payload || {});
      })
      .subscribe(channelStatus => {
        setStatus(channelStatus);
        onStatusRef.current?.(channelStatus);
      });

    return () => {
      channel.unsubscribe();
      channelRef.current = null;
      setStatus("idle");
    };
  }, [client, enabled, sid]);

  const sendEnvelope = useCallback(async envelope => {
    if (!channelRef.current) return;
    await channelRef.current.send({
      type: "broadcast",
      event: REMOTE_EVENT,
      payload: envelope,
    });
  }, []);

  return { status, error, hasConfig, sendEnvelope };
};

export default useRemoteSession;
