import React, { useEffect, useState } from "react";
import { Helmet } from "react-helmet";
import styled from "styled-components";
import Layout from "../components/layout";
import HostPanel from "../components/RemoteLab/HostPanel";
import ControllerPanel from "../components/RemoteLab/ControllerPanel";

const Page = styled.section`
  max-width: 1200px;
  margin: 0 auto;
  color: #fff;
  display: flex;
  flex-direction: column;
  gap: 14px;
`;

const Heading = styled.div`
  text-align: center;

  h1 {
    margin: 0;
    font-size: 2rem;
    color: #f7fbff;
  }

  p {
    margin: 10px auto 0;
    max-width: 760px;
    color: rgba(255, 255, 255, 0.8);
    line-height: 1.45;
  }
`;

const RemoteLabPage = () => {
  const [mode, setMode] = useState("host");
  const [sid, setSid] = useState("");

  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const nextMode = params.get("mode") === "controller" ? "controller" : "host";
    setMode(nextMode);
    setSid(params.get("sid") || "");
  }, []);

  const title = mode === "controller" ? "Remote Lab Controller" : "Remote Lab Host";

  return (
    <Layout>
      <Helmet title={`${title} | Bhimesh Chauhan`} />
      <Page>
        <Heading>
          <h1>Remote Lab</h1>
          <p>
            Scan the QR code from desktop to pair your phone as a realtime trackpad.
            Switch to draw mode on phone to sketch directly on the host canvas.
          </p>
        </Heading>

        {mode === "controller" ? <ControllerPanel sid={sid} /> : <HostPanel />}
      </Page>
    </Layout>
  );
};

export default RemoteLabPage;
